package org.meshtastic.feature.map.planner

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertTrue

/**
 * Regression vectors generated with the NTIA C++ reference (ITM_P2P_TLS_Ex).
 * Row format: `id htx hrx climate N0 fMHz pol eps sigma mdvar time loc sit n step v0..vn | rc A mode warn Aref dh`
 */
class ItmTest {
    @Test
    fun matchesReferenceVectors() {
        var modes = 0
        val seen = mutableSetOf<Int>()
        for (line in VECTORS.lines().filter { it.isNotBlank() }) {
            val (inp, exp) = line.split(" | ")
            val t = inp.trim().split(" ")
            val e = exp.trim().split(" ")
            val id = t[0]
            val n = t[13].toInt()
            val elev = DoubleArray(n + 1) { t[15 + it].toDouble() }
            val r = Itm.pointToPoint(
                elevationsM = elev,
                stepM = t[14].toDouble(),
                txHeightM = t[1].toDouble(),
                rxHeightM = t[2].toDouble(),
                frequencyMHz = t[5].toDouble(),
                surfaceRefractivityNUnits = t[4].toDouble(),
                climate = t[3].toInt(),
                polarization = if (t[6].toInt() == 1) ItmPolarization.VERTICAL else ItmPolarization.HORIZONTAL,
                epsilon = t[7].toDouble(),
                sigma = t[8].toDouble(),
                mdvar = t[9].toInt(),
                timePct = t[10].toDouble(),
                locationPct = t[11].toDouble(),
                situationPct = t[12].toDouble(),
            )
            val expMode = e[2].toInt()
            seen += expMode
            assertEquals(e[0].toInt(), r.returnCode, "$id rc")
            assertEquals(e[1].toDouble(), r.lossDb, 0.01, "$id loss")
            assertEquals(ItmMode.entries[expMode], r.mode, "$id mode")
            assertEquals(e[3].toInt(), r.warnings, "$id warnings")
            assertEquals(e[4].toDouble(), r.referenceAttenuationDb, 0.01, "$id Aref")
            assertEquals(e[5].toDouble(), r.terrainIrregularityM, 0.01, "$id dh")
            modes++
        }
        assertTrue(modes >= 24, "expected at least 24 vectors, got $modes")
        assertEquals(setOf(1, 2, 3), seen, "all propagation modes covered")
    }

    @Test
    fun invalidInputsReturnErrorCodes() {
        val flat = DoubleArray(11) { 100.0 }
        assertEquals(1000, Itm.pointToPoint(flat, 100.0, 0.1, 2.0, 433.0).returnCode)
        assertEquals(1009, Itm.pointToPoint(flat, 100.0, 2.0, 2.0, 5.0).returnCode)
        assertTrue(Itm.pointToPoint(flat, 100.0, 2.0, 2.0, 5.0).lossDb.isNaN())
    }

